const listStreamEntries = `-- name: ListStreamEntries :many
WITH candidates AS (
 SELECT sequence, size_bytes FROM dynamodb_stream_entries
 WHERE stream_arn = ?1 AND shard_id = ?2
 AND (length(ltrim(sequence, '0')), ltrim(sequence, '0')) >=
     (length(ltrim(CAST(?3 AS TEXT), '0')), ltrim(CAST(?3 AS TEXT), '0'))
 AND (CAST(?4 AS BOOLEAN) OR ltrim(sequence, '0') != ltrim(CAST(?3 AS TEXT), '0'))
 ORDER BY length(ltrim(sequence, '0')), ltrim(sequence, '0'), sequence
 LIMIT CAST(?5 AS INTEGER)
), bounded AS (
 SELECT sequence, SUM(COALESCE(size_bytes, 0)) OVER (
  ORDER BY length(ltrim(sequence, '0')), ltrim(sequence, '0'), sequence ROWS UNBOUNDED PRECEDING
 ) AS total_bytes FROM candidates
)
SELECT e.stream_arn, e.shard_id, e.sequence, e.created_at, e.event_id, e.event_name, e.event_source, e.event_version, e.aws_region, e.identity_type, e.identity_principal, e.size_bytes, e.view_type, e.keys_data, e.new_image, e.old_image FROM dynamodb_stream_entries AS e
JOIN bounded AS b ON e.sequence = b.sequence
WHERE e.stream_arn = ?1 AND e.shard_id = ?2 AND b.total_bytes <= 1048576
ORDER BY length(ltrim(e.sequence, '0')), ltrim(e.sequence, '0'), e.sequence
`

